{
  "label": "UNSUPPORTED",
  "rationale": "The evidence outlines a procedure stating that Identity Operations should disable interactive accounts within 24 hours, which reflects policy intent rather than operating effectiveness or proof that accounts are actually disabled within that timeframe.",
  "cited_excerpt": "Identity Operations should disable interactive accounts within 24 hours of the recorded termination time."
}

{
  "label": "SUPPORTED",
  "rationale": "The report confirms that across the sampled terminated identities, the maximum time to disablement was 7 hours 42 minutes, and zero identities exceeded the 24-hour threshold.",
  "cited_excerpt": "Identities exceeding 24 hours: 0"
}

{
  "label": "UNSUPPORTED",
  "rationale": "The evidence outlines a procedure/policy statement that privileged roles should be reviewed every quarter, but does not provide proof that a review was actually completed for the most recent quarter.",
  "cited_excerpt": "Privileged roles should be reviewed every quarter."
}

{
  "label": "SUPPORTED",
  "rationale": "The evidence directly confirms that the Q3 privileged access review covering 34 privileged assignments was completed on 2026-09-28 with zero open items.",
  "cited_excerpt": "Review completed: 2026-09-28"
}

{
  "label": "UNSUPPORTED",
  "rationale": "The evidence outlines a policy requirement stating that data must use encryption at rest, but it does not demonstrate that encryption at rest is actually implemented or active for sensitive production data.",
  "cited_excerpt": "Sensitive production data must use approved encryption at rest."
}

{
  "label": "SUPPORTED",
  "rationale": "The configuration export confirms that encryption at rest is enabled across all production databases and object stores with no exceptions recorded.",
  "cited_excerpt": "Encryption at rest: enabled on 4 of 4\nProduction object stores: 3\nEncryption at rest: enabled on 3 of 3\nExceptions: none recorded."
}

{
  "label": "UNSUPPORTED",
  "rationale": "The evidence outlines a policy standard requiring TLS 1.2 or later rather than technical evidence demonstrating that the public application endpoint actively rejects TLS versions below 1.2.",
  "cited_excerpt": "Externally accessible applications must use TLS 1.2 or later."
}

{
  "label": "SUPPORTED",
  "rationale": "The scan output directly shows that TLS 1.0 and TLS 1.1 are rejected, while TLS 1.2 and TLS 1.3 are accepted by the endpoint.",
  "cited_excerpt": "TLS 1.0: rejected\nTLS 1.1: rejected\nTLS 1.2: accepted\nTLS 1.3: accepted"
}

{
  "label": "UNSUPPORTED",
  "rationale": "The evidence outlines policy requirements rather than operational evidence demonstrating that successful daily backups and a quarterly restore test were actually completed.",
  "cited_excerpt": "Critical systems must be backed up daily. Restore testing should occur at least quarterly and results should be retained."
}

{
  "label": "SUPPORTED",
  "rationale": "The report confirms that all scheduled daily backups for critical systems were successful during the period and a restore test was completed successfully on 2026-09-16.",
  "cited_excerpt": "Daily critical-system backup jobs: 92 scheduled / 92 successful\nMost recent restore test: 2026-09-16\nRestore test result: successful"
}

